import requests
import time

def deny_access(url, seconds=30):
    while True:
        try:
            response = requests.get(url, timeout=seconds)
            if response.status_code == 403:
                break
            else:
                time.sleep(1)
        except Exception as e:
            print(f"Access Denied: {e}")
            time.sleep(10)

if __name__ == "__main__":
    # Example target
    deny_access("https://example.com")
```

